 const rows=lv===1?[['re','play','replay'],['un','lock','unlock'],['help','ful','helpful'],['hope','less','hopeless'],['re','fill','refill'],['un','fair','unfair'],['joy','ful','joyful'],['fear','less','fearless'],['re','read','reread'],['un','pack','unpack'],['re','tell','retell'],['kind','ness','kindness'],['re','build','rebuild'],['un','tie','untie'],['pre','heat','preheat'],['thank','ful','thankful'],['color','less','colorless'],['re','write','rewrite'],['un','safe','unsafe'],['pain','ful','painful'],['rest','less','restless'],['play','ful','playful'],['un','wrap','unwrap'],['sad','ness','sadness'],['use','ful','useful'],['un','load','unload'],['harm','less','harmless'],['soft','ly','softly']]:[['un','kind','ness','unkindness'],['re','paint','ing','repainting'],['care','less','ness','carelessness'],['dis','like','dislike'],['re','start','ing','restarting'],['un','help','ful','unhelpful'],['dis','agree','ment','disagreement'],['hope','less','ness','hopelessness'],['re','play','ing','replaying'],['care','ful','careful'],['un','friend','ly','unfriendly'],['re','open','ing','reopening'],['dis','obey','disobey'],['mis','spell','misspell'],['pre','view','preview'],['un','break','able','unbreakable'],['re','fresh','ment','refreshment'],['dis','honest','dishonest'],['un','comfort','able','uncomfortable'],['thank','ful','ness','thankfulness'],['un','safe','ly','unsafely'],['mis','understand','ing','misunderstanding'],['dis','appear','ance','disappearance'],['pain','less','ly','painlessly'],['help','less','ness','helplessness'],['play','ful','ly','playfully'],['re','tell','ing','retelling']];
 const r=pick(rows),word=r[r.length-1],parts=r.slice(0,-1);
 return item(B('Join these word parts. Which word do they make?','낱말 조각을 합치면 어떤 낱말이 될까요?'),parts.join(' + '),word,[parts.slice().reverse().join(''),parts[0]+parts[0]+parts.slice(1).join('')]);
